fn mat(m:&mut Assets<StandardMaterial>,r:f32,g:f32,b:f32,metal:f32)->Handle<StandardMaterial>{m.add(StandardMaterial{base_color:Color::srgb(r,g,b),metallic:metal,perceptual_roughness:0.48,..default()})}
fn block(c:&mut Commands,mesh:&Handle<Mesh>,m:&Handle<StandardMaterial>,p:Vec3,s:Vec3)->Entity{c.spawn((Mesh3d(mesh.clone()),MeshMaterial3d(m.clone()),Transform::from_translation(p).with_scale(s))).id()}
fn graph()->(Vec<Vec3>,Vec<Vec<usize>>){
 let mut nodes=Vec::new(); for z in AISLES {for x in [-42.,0.,42.] {nodes.push(Vec3::new(x,0.14,z));}}
 let mut edges=vec![vec![];15];fn connect(e:&mut Vec<Vec<usize>>,a:usize,b:usize){e[a].push(b);e[b].push(a);}
 for row in 0..4 {for col in 0..3 {connect(&mut edges,row*3+col,(row+1)*3+col);}}
 for row in 1..4 {connect(&mut edges,row*3,row*3+1);connect(&mut edges,row*3+1,row*3+2);}
 // Edge amenities occupy the outer ends of +/-27m aisles. Small perimeter detours
 // at +/-31m keep the route and every walker outside their occupied footprints.
 for row in [0,4] {let z=AISLES[row];for side in [-1.,1.] {let outer=row*3+if side<0.{0}else{2};let center=row*3+1;let start=nodes.len();for p in [Vec3::new(side*24.,0.14,z),Vec3::new(side*24.,0.14,z.signum()*31.),Vec3::new(side*42.,0.14,z.signum()*31.)] {nodes.push(p);edges.push(vec![]);}connect(&mut edges,center,start);connect(&mut edges,start,start+1);connect(&mut edges,start+1,start+2);connect(&mut edges,start+2,outer);}}
 (nodes,edges)
}
fn shortest(nodes:&[Vec3],edges:&[Vec<usize>],start:usize,end:usize)->Vec<Vec3>{let n=nodes.len();let mut distance=vec![f32::INFINITY;n];let mut previous=vec![usize::MAX;n];let mut seen=vec![false;n];distance[start]=0.;for _ in 0..n {let u=(0..n).filter(|i|!seen[*i]).min_by(|a,b|distance[*a].total_cmp(&distance[*b])).unwrap();if u==end{break;}seen[u]=true;for &v in &edges[u]{let d=distance[u]+nodes[u].distance(nodes[v]);if d<distance[v]{distance[v]=d;previous[v]=u;}}}let mut ids=vec![end];let mut u=end;while u!=start {u=previous[u];if u==usize::MAX{break;}ids.push(u);}ids.reverse();ids.iter().map(|i|nodes[*i]).collect()}
